slug=lambda s: re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')[:40]
out=[]
for code, items in P.items():
    assert len(items)==10
    for n,b,s,d,pr,m,st in items:
        assert pr<=m and len(n)<=200 and len(s)<=500
        out.append({"categoryCode":code,"name":n,"brand":b,"summary":s,"description":d,
            "price":float(pr),"mrp":float(m),"currency":"INR","stockQuantity":st,
            "imageUrl":f"https://picsum.photos/seed/{slug(n)}/600/600"})
json.dump(out,open("products-new-categories.json","w",encoding="utf-8"),indent=2,ensure_ascii=False)
print(len(out))
